/* ---------- Dados ---------- */
let adm=[],admError='';
const admOf=k=>adm.filter(x=>x.kind===k);
const admById=id=>adm.find(x=>x.id===id);
const isAnalyst=()=>me()?.role==='analista',isContracts=()=>me()?.role==='contratos';
// Quem pode receber tarefa do cronograma: o administrativo e a gestão.
const taskPeople=()=>db.users.filter(u=>['gestor',...OFFICE_ROLES].includes(u.role)&&u.active&&!u.archived&&!u.pending).sort((a,b)=>(a.role==='gestor')-(b.role==='gestor')||byName(a,b));
const officePeople=()=>db.users.filter(u=>OFFICE_ROLES.includes(u.role)&&!u.archived&&!u.pending&&u.active);
const admErrText=e=>!e?'Não foi possível salvar.':/adm_items|relation|schema cache|PGRST20[05]/i.test(`${e.message} ${e.code}`)?'Falta atualizar o banco: execute supabase/administrativo.sql no Supabase.':/fetch|network/i.test(e.message||'')?'Sem internet. Tente de novo.':/row-level|permission/i.test(e.message||'')?'Seu perfil não pode alterar isso.':'Não foi possível salvar: '+e.message;
async function loadAdm(){if(!me()||!(isManager()||isOffice())){adm=[];admError='';return}
 try{adm=await fetchAll('adm_items','*',q=>q,'id');admError=''}catch(e){adm=[];admError=/adm_items|relation|PGRST20[05]|schema cache/i.test(`${e.message} ${e.code}`)?'Falta atualizar o banco: execute supabase/administrativo.sql no SQL Editor do Supabase.':'Não foi possível carregar os dados. Confira a internet.'}}
{const base=loadCounts;loadCounts=async function(){await base();await loadAdm();clearTimeout(admNewsTimer);admNewsTimer=setTimeout(showAdmNews,700)}}
// Novidades do cronograma em popup: tarefa nova para mim, transferência para aceitar e resposta às que enviei. Cada aviso aparece uma vez.
let admNewsTimer=null;
const newsKey=()=>`gav-novidades:${authId}`;
function admNews(){if(!me()||!(isOffice()||isManager()))return [];const out=[],name=id=>esc(shortName(userById(id)?.name||'—'));
 for(const t of admOf('tarefa'))if(taskActive(t)&&!pontualDone(t)&&(t.data.assignees||[]).includes(authId)&&t.created_by!==authId)out.push({key:'t:'+t.id,html:`<b>Nova tarefa:</b> ${esc(t.data.title)}<small>${esc(taskDesc(t))} · criada por ${esc(shortName(t.created_by_name))}</small>`});
 for(const x of transfersPendingTo(authId))out.push({key:`x:${x.id}:pendente`,act:x,html:`<b>${esc(shortName(x.created_by_name))} quer passar uma tarefa para você:</b> ${esc(admById(x.data.task)?.data.title||x.data.title||'')}${x.created_by!==x.data.from?`<small>Era de ${name(x.data.from)}</small>`:''}`});
 for(const x of admOf('tarefa_transf'))if(x.created_by===authId&&x.data.to!==authId&&['aceita','recusada'].includes(x.data.status)&&x.data.answeredAt)out.push({key:`x:${x.id}:${x.data.status}`,html:`<b>${name(x.data.to)} ${x.data.status==='aceita'?'aceitou':'recusou'}</b> a tarefa ${esc(x.data.title||'')}${x.data.status==='recusada'?'<small>A tarefa continua com quem estava.</small>':''}`});
 return out}
function readSeen(){try{const v=JSON.parse(localStorage.getItem(newsKey())||'null');return Array.isArray(v)?new Set(v):null}catch(e){return null}}
function writeSeen(set){try{localStorage.setItem(newsKey(),JSON.stringify([...set].slice(-400)))}catch(e){}}
function showAdmNews(){if(!me()||document.querySelector('.dialog')||document.querySelector('#login-form'))return;const all=admNews();let seen=readSeen();
 if(!seen){seen=new Set(all.filter(x=>!x.act).map(x=>x.key));writeSeen(seen)}
 const fresh=all.filter(x=>!seen.has(x.key));if(!fresh.length)return;for(const x of fresh)seen.add(x.key);writeSeen(seen);navigator.vibrate?.([20,60,20]);
 openModal(modalHead('Novidades')+`<div class="news-list">${fresh.map(x=>`<div class="news-item${x.act?' act':''}">${icon(x.act?'swap':'bell')}<div class="grow">${x.html}${x.act?`<div class="incoming-actions"><button class="button compact" data-action="adm-transfer-accept" data-id="${x.act.id}">${icon('check')}Aceitar</button><button class="button compact outline" data-action="adm-transfer-decline" data-id="${x.act.id}">Recusar</button></div>`:''}</div></div>`).join('')}</div><div class="dialog-actions"><button class="button outline" data-action="adm-news-ok">Ok</button>${view.page!=='o-tasks'?`<button class="button" data-action="adm-news-go">Ver cronograma</button>`:''}</div>`);
 document.querySelector('.dialog')?.classList.add('news')}
// Duas pessoas no mesmo registro: antes de salvar, junta comentários e histórico da versão mais nova do servidor.
const entryKey=e=>`${e?.at}|${e?.by}|${e?.text}`;
function mergeEntries(a=[],b=[]){const seen=new Set(),out=[];for(const e of [...a,...b]){const k=entryKey(e);if(!seen.has(k)){seen.add(k);out.push(e)}}return out.sort((x,y)=>String(x.at).localeCompare(String(y.at)))}
async function admSave(kind,data,id){if(id){try{const {data:fresh}=await sb.from('adm_items').select().eq('id',id).maybeSingle();if(fresh?.data){for(const k of ['comments','log'])if(Array.isArray(fresh.data[k])||Array.isArray(data[k]))data={...data,[k]:mergeEntries(fresh.data[k],data[k])}}}catch(e){}}
 const q=id?sb.from('adm_items').update({data}).eq('id',id):sb.from('adm_items').insert({kind,data});
 const {data:row,error}=await q.select().maybeSingle();if(error||!row){toast(admErrText(error));return null}
 const i=adm.findIndex(x=>x.id===row.id);if(i>=0)adm[i]=row;else adm.push(row);return row}
// Histórico: cada lançamento guarda quem fez o quê e quando.
const logEntry=text=>({at:new Date().toISOString(),by:me().name,text});
const withLog=(old,data,text)=>text?{...data,log:[...(old?.log||[]),logEntry(text)]}:{...data,log:old?.log||[]};
function historyDialog(x){const log=(x?.data.log||[]).slice().reverse();openModal(modalHead('Histórico')+`<p class="subtitle">Registrado por ${esc(x.created_by_name||'—')} em ${dateBR(x.created_at)} às ${timeOf(x.created_at)}.</p>${log.length?`<div class="history">${log.map(h=>`<p><span>${esc(h.text)}</span><small>${esc(h.by)} · ${dateBR(h.at)} às ${timeOf(h.at)}</small></p>`).join('')}</div>`:'<p class="micro">Sem alterações registradas.</p>'}`)}
async function admRemove(id){const {error}=await sb.from('adm_items').delete().eq('id',id);if(error){toast(admErrText(error));return false}adm=adm.filter(x=>x.id!==id);return true}

/* ---------- Formatos ---------- */
const brl=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
// Dia no horário de Brasília (as datas de criação vêm do servidor em UTC).
const spDay=iso=>iso?new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date(iso)):'';
const dateBR=d=>{if(!d)return '';const s=String(d);return (s.length>10?spDay(s):s.slice(0,10)).split('-').reverse().join('/')};
const monthLabel=m=>{const [y,mm]=m.split('-').map(Number);return new Date(y,mm-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}).replace(/^./,c=>c.toUpperCase())};
const shiftMonth=(m,n)=>{const [y,mm]=m.split('-').map(Number),d=new Date(y,mm-1+n,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
// Valor em reais no campo: 1500 → 1.500,00 (ao sair do campo).
function moneyText(v){if(v==null||v==='')return '';const n=Number(v);return Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}):''}
document.addEventListener('focusout',e=>{const i=e.target;if(!(i instanceof HTMLInputElement)||!i.hasAttribute('data-money'))return;const v=parseMoney(i.value);if(Number.isFinite(v))i.value=moneyText(v)});
// CPF (11 números) ou CNPJ (14) com pontos, barra e traço, enquanto digita. Texto que não é só número fica como está.
function docMask(v){const raw=String(v??'');if(/[^\d.\/\-\s]/.test(raw))return raw.trim();const d=raw.replace(/\D/g,'').slice(0,14);if(!d)return '';
 return d.length<=11?d.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d{1,2})$/,'.$1-$2')
  :d.replace(/^(\d{2})(\d{3})(\d{3})(\d{1,4})(\d{0,2})$/,(m,a,b,c,e,f)=>`${a}.${b}.${c}/${e}${f?'-'+f:''}`)}
document.addEventListener('input',e=>{const i=e.target;if(!(i instanceof HTMLInputElement)||!i.hasAttribute('data-doc'))return;const atEnd=i.selectionStart===i.value.length,m=docMask(i.value);if(m!==i.value){i.value=m;if(atEnd)i.setSelectionRange(m.length,m.length)}});
function parseMoney(s){let t=String(s??'').trim().replace(/[R$\s]/g,'');if(!t)return NaN;if(t.includes(','))t=t.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(t))t=t.replace(/\./g,'');const v=Number(t);return Number.isFinite(v)?Math.round(v*100)/100:NaN}
const moneyInput=(name,v,label,req=true)=>`<label class="field"><span>${label}</span><span class="money-in"><b>R$</b><input name="${name}" data-money inputmode="decimal" ${req?'required':''} placeholder="0,00" value="${esc(moneyText(v))}"></span></label>`;
const dateInput=(name,v,label,req=false)=>`<label class="field"><span>${label}</span><input name="${name}" type="date" ${req?'required':''} value="${esc(v||'')}"></label>`;
const daysAgo=d=>{const n=Math.round((parseDate(today())-parseDate(d))/864e5);return n<=0?'hoje':n===1?'ontem':`há ${n} dias`};
function monthNav(m,action){return `<div class="month-nav"><button class="icon-btn" data-action="${action}" data-step="-1" aria-label="Mês anterior">${icon('back')}</button><strong>${monthLabel(m)}</strong><button class="icon-btn" data-action="${action}" data-step="1" aria-label="Próximo mês">${icon('chevron')}</button></div>`}
const admNotice=()=>admError?`<div class="notice">${icon('info')}<div><strong>Área administrativa indisponível</strong>${esc(admError)}</div></div>`:'';
const stampLine=x=>`<p class="micro">Registrado por ${esc(x.created_by_name||'—')} em ${dateBR(x.created_at)}${x.updated_at&&x.updated_at!==x.created_at&&x.updated_by_name?` · última alteração: ${esc(x.updated_by_name)}, ${dateBR(x.updated_at)} às ${timeOf(x.updated_at)}`:''}.</p>`;
// Valor por extenso para o recibo.
function extenso(v){const u=['','um','dois','três','quatro','cinco','seis','sete','oito','nove','dez','onze','doze','treze','catorze','quinze','dezesseis','dezessete','dezoito','dezenove'],d=['','','vinte','trinta','quarenta','cinquenta','sessenta','setenta','oitenta','noventa'],c=['','cento','duzentos','trezentos','quatrocentos','quinhentos','seiscentos','setecentos','oitocentos','novecentos'];
 const tri=n=>{if(n===100)return 'cem';const p=[];if(n>=100){p.push(c[Math.floor(n/100)]);n%=100}if(n>=20){p.push(d[Math.floor(n/10)]);n%=10}if(n)p.push(u[n]);return p.join(' e ')};
 const num=n=>{if(!n)return 'zero';const parts=[],mi=Math.floor(n/1e6),mil=Math.floor(n%1e6/1000),r=n%1000;if(mi)parts.push(tri(mi)+(mi>1?' milhões':' milhão'));if(mil)parts.push(mil===1?'mil':tri(mil)+' mil');if(r)parts.push(tri(r));return parts.length>1&&(r<=100||r%100===0)&&r?parts.slice(0,-1).join(', ')+' e '+parts.at(-1):parts.join(r&&parts.length>1?', ':' e ')};
 const cents=Math.round(v*100),reais=Math.floor(cents/100),cent=cents%100,out=[];
 if(reais)out.push(num(reais)+(reais%1e6===0?' de':'')+(reais===1?' real':' reais'));if(cent)out.push(num(cent)+(cent===1?' centavo':' centavos'));return out.join(' e ')||'zero real'}

