const OFFICE_PAGES={'o-hub':oHub,'o-tasks':oTasks,'o-tickets':oTickets,'o-notes':oNotes,'o-partners':oPartners,'o-orders':oOrders,'o-order':oOrder,'o-cash':oCash,'o-cash-config':oCashConfig,'o-contracts':oContracts};
// Funções do administrativo. Cada função tem o padrão dela; a gestão pode liberar outras para cada pessoa.
const ADM_MODULES=[['contratos','Auditoria de contratos','file',['o-contracts']],['chamados','Chamados','ticket',['o-tickets']],['notas','Notas fiscais','receipt',['o-notes','o-partners']],['pedidos','Pedidos','truck',['o-orders','o-order']],['caixas','Caixas','wallet',['o-cash']]];
const DEFAULT_MODULES={analista:['notas','pedidos','caixas'],contratos:['contratos','chamados']};
const officeModules=(u=me())=>Array.isArray(u?.adm_modules)?u.adm_modules:DEFAULT_MODULES[u?.role]||[];
function officePages(){if(isManager())return OFFICE_PAGES;const mods=officeModules();return Object.fromEntries(['o-tasks',...ADM_MODULES.filter(([k])=>mods.includes(k)).flatMap(x=>x[3])].map(k=>[k,OFFICE_PAGES[k]]))}
function officeModulesField(u,role){const cur=Array.isArray(u?.adm_modules)?u.adm_modules:DEFAULT_MODULES[role]||[];return `<div class="field"><span>Funções liberadas</span><div class="check-list">${ADM_MODULES.map(([k,l])=>`<label class="check-row"><input type="checkbox" name="modules" value="${k}" ${cur.includes(k)?'checked':''}><span>${l}${(DEFAULT_MODULES[role]||[]).includes(k)?'<small>Padrão da função</small>':''}</span></label>`).join('')}</div><small class="muted">O cronograma é de todos. Marque o que esta pessoa também faz.</small></div>`}
Object.assign(PAGE_META,{'o-hub':['Administrativo','Visão geral'],'o-tasks':['Administrativo','Cronograma'],'o-tickets':['Administrativo','Chamados'],'o-notes':['Administrativo','Notas fiscais'],'o-partners':['Administrativo','Parceiros'],'o-orders':['Administrativo','Pedidos'],'o-order':['Administrativo','Pedido'],'o-cash':['Administrativo','Caixas'],'o-cash-config':['Administrativo','Configurar caixas'],'o-contracts':['Administrativo','Auditoria de contratos']});
ROOTS.push('o-hub','o-tasks','o-contracts','o-tickets','o-notes','o-orders','o-cash');
Object.assign(SECTOR_OF,Object.fromEntries(Object.keys(OFFICE_PAGES).map(k=>[k,'adm'])));
function officeNav(){const p=view.page,b=(pages,act,ic,label)=>`<button class="${pages.includes(p)?'active':''}"${pages.includes(p)?' aria-current="page"':''} data-action="${act}">${icon(ic)}${label}</button>`;
 const short={contratos:'Contratos',chamados:'Chamados',notas:'Notas',pedidos:'Pedidos',caixas:'Caixas'},mods=officeModules(),items=[[['o-tasks'],'o-tasks','tasks','Tarefas'],...ADM_MODULES.filter(([k])=>mods.includes(k)).map(([k,,ic,pages])=>[pages,pages[0],ic,short[k]])];
 return `<nav class="bottom-nav" aria-label="Navegação principal">${items.map(x=>b(...x)).join('')}${b(['profile'],'profile','user','Perfil')}</nav>`}
function officeSideGroups(){if(isManager())return ['Administrativo',[['o-hub','briefcase','Visão geral',['o-hub']],['o-tasks','tasks','Cronograma',['o-tasks']],['o-contracts','file','Contratos',['o-contracts'],newContractErrors().length||0],['o-tickets','ticket','Chamados',['o-tickets'],newTickets().length||0],['o-notes','receipt','Notas fiscais',['o-notes','o-partners']],['o-orders','truck','Pedidos',['o-orders','o-order'],openOrders().length||0],['o-cash','wallet','Caixas',['o-cash','o-cash-config']]]];
 const mods=officeModules();return [['',[['o-tasks','tasks','Tarefas',['o-tasks']],...ADM_MODULES.filter(([k])=>mods.includes(k)).map(([k,l,ic,pages])=>[pages[0],ic,l,pages,k==='contratos'?admOf('contrato').filter(c=>!c.data.audit).length||0:k==='notas'?pendingPartners().length||0:0])]]]}
TOURS.analista=[['briefcase','Bem-vindo(a) à GAV!','Aqui fica o seu dia no administrativo: tarefas, notas, pedidos e caixas.'],['tasks','Cronograma','Em Tarefas aparecem as tarefas do dia. Toque para marcar como feita.'],['receipt','Notas e pedidos','Registre cada etapa das notas (recebida, vouchers, Zeev, pagamento) e a chegada dos pedidos, com o que veio errado.'],['wallet','Caixas','Lance cada pagamento, imprima o recibo para assinar e acompanhe o saldo de cada equipe.']];
TOURS.contratos=[['briefcase','Bem-vindo(a) à GAV!','Aqui fica o seu dia no administrativo.'],['tasks','Cronograma','Em Tarefas aparecem as tarefas do dia. Toque para marcar como feita.'],['ticket','Chamados','Registre o número e a data de cada chamado aberto e marque como feito quando finalizar. O botão Copiar copia a lista para enviar.']];

/* ---------- Visão geral (gestão) ---------- */
function oHub(){const d=today(),m=d.slice(0,7),mm=monthLabel(m).split(' ')[0].toLowerCase(),cs=admOf('contrato').filter(c=>String(c.data.dataVenda||'').slice(0,7)===m),tasks=tasksOn(d),done=tasks.filter(t=>doneOf(t.id,d)).length,late=lateTasks().length+pontualLate().length,open=ticketsOpen().length,nt=newTickets().length,people=officePeople(),lv=k=>cs.filter(c=>contractLevel(c)===k).length,aud=cs.filter(c=>c.data.audit).length;
 const ns=NOTE_TYPES.map(([t])=>noteSummary(t,m)),pend=ns.reduce((a,x)=>a+x.pend+x.prob,0),launched=ns.reduce((a,x)=>a+x.launched,0),due=ns.reduce((a,x)=>a+x.due,0);
 const ords=orders().filter(o=>orderMonth(o)===m&&o.data.arrivedAt),oo=openOrders().length,cx=cashes().filter(c=>c.data.active!==false);
 const row=(act,ic,title,big,sub,tone='')=>`<button class="hub-row ${tone}" data-action="${act}"><span class="hub-ic">${icon(ic)}</span><span class="grow"><strong>${title}</strong><small>${sub}</small></span><span class="hub-big">${big}</span>${icon('chevron','chevron')}</button>`;
 return sectorTabs('adm')+pageHead('Administrativo','Visão geral',`Resumo de hoje e de ${mm}.`)+admNotice()+`
 ${people.length?'':`<button class="tile pending-tile" data-action="g-asgs"><span class="tile-icon">${icon('users')}</span><span class="grow"><strong>Ninguém do administrativo cadastrado</strong><span class="muted">Cadastre assistentes de contratos e analistas em Pessoas → Administrativo.</span></span>${icon('chevron','chevron')}</button>`}
 <div class="hub-list">
  ${row('o-tasks','tasks','Cronograma',`${done}<em>/${tasks.length}</em>`,`feitas hoje${late?` · <b class="late-text">${plural(late,'atrasada','atrasadas')}</b>`:''}`,late?'late':'')}
  ${row('o-contracts','file','Contratos',`${aud}<em>/${cs.length}</em>`,`auditados em ${mm} · <span class="lv-inline">${levelDot('grave')}${lv('grave')} ${levelDot('medio')}${lv('medio')} ${levelDot('ok')}${lv('ok')}</span>`,lv('grave')?'late':'')}
  ${row('o-tickets','ticket','Chamados',`${open}`,`em aberto${nt?` · <b>${plural(nt,'novo','novos')}</b>`:''}`)}
  ${row('o-notes','receipt','Notas fiscais',`${launched}<em>/${due}</em>`,`lançadas no Zeev em ${mm}${pend?` · <b class="late-text">${plural(pend,'pendente','pendentes')}</b>`:''}`,pend?'warn':'')}
  ${row('o-orders','truck','Pedidos',`${ords.length}`,`${ords.length===1?'chegou':'chegaram'} em ${mm}${oo?` · <b class="late-text">${plural(oo,'com pendência','com pendência')}</b>`:''}`,oo?'warn':'')}
  ${cx.length?cx.map(c=>{const sm=cashSummary(c,m),wait=sm.ps.filter(p=>!payPaid(p)).length;return row('o-cash','wallet',esc(c.data.name),`<span class="hub-money">${brl(sm.left)}</span>`,`saldo de ${mm}${wait?` · <b class="late-text">${plural(wait,'aguardando pagamento','aguardando pagamento')}</b>`:''}`,sm.left<0||wait?'warn':'')}).join(''):row('o-cash','wallet','Caixas','—','nenhum caixa configurado')}
 </div>`}

/* ---------- Cronograma ---------- */
const taskActive=t=>t.data.active!==false;
const taskStart=t=>{const s=t.data.start||today(),c=spDay(t.created_at);return c&&c>s?c:s};
// Tarefa pontual: sem data fixa, fica na lista de hoje até alguém concluir (com prazo opcional).
const isPontual=t=>t.data.mode==='pontual';
function pontualOn(t,d){if(d<spDay(t.created_at))return false;const f=doneOf(t.id,d);return f?f.data.date===d:d===today()}
const taskDesc=t=>isPontual(t)?`Pontual, até concluir${t.data.due?` · prazo ${dateBR(t.data.due)}`:''}`:describeRepeat({start:t.data.start,end:t.data.end,repeat:t.data.repeat});
// Pontual concluída some das listas de tarefas cadastradas (fica no dia em que foi feita e no histórico).
const pontualDone=t=>isPontual(t)&&!!doneOf(t.id,today());
const lateP=(t,d)=>isPontual(t)&&t.data.due&&t.data.due<d&&!doneOf(t.id,d);
// Transferência: a tarefa daquele dia passa de uma pessoa para outra (pontual: até ser concluída). O cadastro não muda.
const transfersOf=task=>admOf('tarefa_transf').filter(x=>x.data.task===task).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));
// Transferência para outra pessoa fica pendente até ela aceitar; só depois a tarefa muda de dono.
const transferOk=x=>!x.data.status||x.data.status==='aceita';
const transferApplies=(t,x,d)=>transferOk(x)&&(isPontual(t)?x.data.date<=d:x.data.date===d);
const transferOpen=x=>{const t=admById(x.data.task);return x.data.status==='pendente'&&t&&taskActive(t)&&(isPontual(t)?!doneOf(t.id,today()):x.data.date>=today())};
const transfersPendingTo=who=>admOf('tarefa_transf').filter(x=>x.data.to===who&&transferOpen(x));
const transferPendingFrom=(t,d,from)=>admOf('tarefa_transf').find(x=>x.data.task===t.id&&x.data.from===from&&transferOpen(x)&&(isPontual(t)||x.data.date===d));
function assigneesOn(t,d){let a=[...(t.data.assignees||[])];for(const x of transfersOf(t.id))if(transferApplies(t,x,d)&&a.includes(x.data.from)){a=a.filter(i=>i!==x.data.from);if(!a.includes(x.data.to))a.push(x.data.to)}return a}
const transferInto=(t,d,who)=>transfersOf(t.id).filter(x=>transferApplies(t,x,d)&&x.data.to===who).at(-1);
const pontualLate=who=>admOf('tarefa').filter(t=>taskActive(t)&&isPontual(t)&&t.data.due&&t.data.due<today()&&!doneOf(t.id,today())&&(!who||assigneesOn(t,today()).includes(who)));
const tasksOn=(d,who)=>admOf('tarefa').filter(t=>taskActive(t)&&(isPontual(t)?pontualOn(t,d):occursOn({start:t.data.start||today(),end:t.data.end,repeat:t.data.repeat},d)&&d>=taskStart(t))&&(!who||assigneesOn(t,d).includes(who))).sort((a,b)=>String(a.data.title).localeCompare(b.data.title,'pt-BR'));
const doneOf=(task,d)=>{const t=admById(task);return admOf('tarefa_feita').find(x=>x.data.task===task&&(t&&isPontual(t)||x.data.date===d))};
function lateTasks(who){const out=[];for(let i=1;i<=14;i++){const d=addDays(today(),-i);for(const t of tasksOn(d,who))if(!doneOf(t.id,d))out.push({t,d})}return out}
const assigneeNames=t=>(t.data.assignees||[]).map(id=>userById(id)).filter(Boolean).map(u=>shortName(u.name)).join(', ')||'Sem responsável';
function admTaskRow(t,d,showWho,person){const f=doneOf(t.id,d),canUndo=f&&(isManager()||f.created_by===authId),tr=person&&transferInto(t,d,person),wait=person&&!f&&transferPendingFrom(t,d,person),canMove=person&&!f&&!wait&&d>=today()&&(isManager()||isOffice());return `<div class="adm-task${f?' done':''}"><button class="adm-check" data-action="adm-done" data-task="${t.id}" data-date="${d}" ${f&&!canUndo?'disabled':''} aria-pressed="${!!f}" aria-label="${f?'Desmarcar':'Marcar como feita'}: ${esc(t.data.title)}">${icon('check')}</button><div class="grow"><strong>${esc(t.data.title)}</strong>${t.data.notes?`<p>${esc(t.data.notes)}</p>`:''}<small>${f?`Feita por ${esc(shortName(f.created_by_name))} às ${timeOf(f.created_at)}${f.data.date!==spDay(f.created_at)?` de ${dateBR(f.created_at)}`:''}`:isPontual(t)?`${t.data.due&&t.data.due<today()?'<b class="late-text">':''}${esc(taskDesc(t))}${t.data.due&&t.data.due<today()?' · prazo vencido</b>':''}`:d<today()?`Era para ${dateBR(d)} · ${daysAgo(d)}`:esc(taskDesc(t))}${showWho?` · ${esc(assigneeNames(t))}`:''}</small>${tr?`<small class="transf-note">${icon('swap')}Transferida de ${esc(shortName(userById(tr.data.from)?.name||'—'))} por ${esc(shortName(tr.created_by_name))}${isManager()||tr.created_by===authId?` · <button class="link-btn" data-action="adm-transfer-undo" data-id="${tr.id}">desfazer</button>`:''}</small>`:''}${wait?`<small class="transf-note wait">${icon('clock')}Aguardando ${esc(shortName(userById(wait.data.to)?.name||'—'))} aceitar${isManager()||wait.created_by===authId?` · <button class="link-btn" data-action="adm-transfer-undo" data-id="${wait.id}">cancelar</button>`:''}</small>`:''}</div>${canMove?`<button class="transf-btn" data-action="adm-task-transfer" data-task="${t.id}" data-date="${d}" data-from="${person}" aria-label="Transferir: ${esc(t.data.title)}">${icon('swap')}<span>Transferir</span></button>`:''}</div>`}
// Equipe hoje: as tarefas do dia das colegas do administrativo (para cobrir atestado e folga).
function teamToday(d){const others=officePeople().filter(p=>p.id!==authId).sort(byName).map(p=>({p,list:tasksOn(d,p.id)})).filter(x=>x.list.length);if(!others.length)return '';
 return `<div class="section-title"><h2>Equipe hoje</h2><small>pode concluir ou transferir</small></div>${others.map(x=>{const done=x.list.filter(t=>doneOf(t.id,d)).length;return `<details class="team-day"${done<x.list.length?' open':''}><summary><span class="pick-avatar sm">${esc(initials(x.p.name))}</span><strong>${esc(shortName(x.p.name))}</strong><small>${done} de ${x.list.length} feitas</small></summary><div class="adm-list">${x.list.map(t=>admTaskRow(t,d,false,x.p.id)).join('')}</div></details>`}).join('')}`}
function transferDialog(taskId,d,from){const t=admById(taskId);if(!t)return;const now=assigneesOn(t,d),opts=(isManager()?taskPeople():officePeople()).filter(p=>p.id!==from&&!now.includes(p.id)).sort(byName);
 openModal(modalHead('Transferir tarefa')+`<p class="subtitle"><b>${esc(t.data.title)}</b><br>De ${esc(shortName(userById(from)?.name||'—'))} · ${isPontual(t)?'até ser concluída':d===today()?'só hoje':'só em '+dateBR(d)}. ${isPontual(t)?'':'Nos outros dias continua como está no cronograma.'}</p><form id="adm-form" data-kind="tarefa_transf" data-task="${t.id}" data-date="${d}" data-from="${from}" autocomplete="off">${opts.length?`<div class="field"><span>Para quem?</span><div class="who-pick">${opts.map(p=>`<label class="who-chip"><input type="radio" name="to" value="${p.id}" required><span>${icon('check')}${esc(shortName(p.name))}</span></label>`).join('')}</div></div>`:'<p class="micro">Não há outra pessoa disponível.</p>'}<p class="form-error" role="alert"></p><p class="micro">A pessoa precisa aceitar. Até lá, a tarefa continua com ${esc(shortName(userById(from)?.name||'quem está'))}.</p><p class="form-error" role="alert"></p><button class="button" type="submit" ${opts.length?'':'disabled'}>Transferir</button></form>`)}
function incomingCard(x){const t=admById(x.data.task);return `<div class="incoming"><div class="grow"><strong>${esc(t?.data.title||x.data.title||'Tarefa')}</strong><small>De ${esc(shortName(userById(x.data.from)?.name||'—'))}${x.created_by!==x.data.from?`, enviada por ${esc(shortName(x.created_by_name))}`:''} · ${t&&isPontual(t)?'até concluir':x.data.date===today()?'só hoje':'só em '+dateBR(x.data.date)}</small></div><div class="incoming-actions"><button class="button compact" data-action="adm-transfer-accept" data-id="${x.id}">${icon('check')}Aceitar</button><button class="button compact outline" data-action="adm-transfer-decline" data-id="${x.id}">Recusar</button></div></div>`}
function incomingHtml(){const xs=transfersPendingTo(authId);return xs.length?`<div class="section-title"><h2>Para aceitar</h2><small>${xs.length}</small></div><div class="incoming-list">${xs.map(incomingCard).join('')}</div>`:''}
async function answerTransfer(x,ok){if(!x||x.data.to!==authId||x.data.status!=='pendente')return;const r=await admSave('tarefa_transf',{...x.data,status:ok?'aceita':'recusada',answeredAt:new Date().toISOString(),answeredBy:me().name},x.id);if(r){if(document.querySelector('.dialog.news'))closeModal();render();toast(ok?'Tarefa aceita. Já está na sua lista.':'Transferência recusada.')}}
function oTasks(){if(isManager())return oTasksManager();const u=me(),d=today(),list=tasksOn(d,u.id),late=[...lateTasks(u.id),...pontualLate(u.id).map(t=>({t,d:today()}))],done=list.filter(t=>doneOf(t.id,d)).length,pc=list.length?Math.round(done/list.length*100):100,own=admOf('tarefa').filter(t=>t.created_by===authId&&!pontualDone(t)).sort((a,b)=>String(a.data.title).localeCompare(b.data.title,'pt-BR'));
 const next=[];for(let i=1;i<=6;i++){const dd=addDays(d,i);for(const t of tasksOn(dd,u.id))next.push({t,dd})}
 return `<p class="eyebrow">${esc(longDate(d))}</p><h1>${greet(u.name)}</h1><p class="subtitle">Seu cronograma de hoje. Toque na tarefa quando terminar.</p>${admNotice()}<button class="button outline compact self-task" data-action="adm-task-new">${icon('plus')}Criar tarefa para mim</button>
 ${incomingHtml()}
 <div class="progress-block"><div class="progress-top"><strong>${done} de ${list.length} feitas</strong><span>${pc}%</span></div><div class="track"><i style="width:${pc}%"></i></div></div>
 ${late.length?`<div class="section-title"><h2>Atrasadas</h2><small>${late.length}</small></div><div class="adm-list">${late.map(x=>admTaskRow(x.t,x.d,false,u.id)).join('')}</div>`:''}
 <div class="section-title"><h2>Hoje</h2><small>${list.filter(t=>!lateP(t,d)).length}</small></div>${list.filter(t=>!lateP(t,d)).length?`<div class="adm-list">${list.filter(t=>!lateP(t,d)).map(t=>admTaskRow(t,d,false,u.id)).join('')}</div>`:`<div class="empty">${icon('sparkles')}Nenhuma tarefa para hoje.</div>`}
 ${teamToday(d)}
 ${next.length?`<div class="section-title"><h2>Próximos dias</h2></div><div class="adm-next">${next.slice(0,12).map(x=>`<p><span>${esc(x.t.data.title)}</span><small>${x.dd===addDays(d,1)?'amanhã':esc(longDate(x.dd).split(',')[0])+' '+shortDate(x.dd)}</small></p>`).join('')}</div>`:''}
 ${own.length?`<div class="section-title"><h2>Tarefas que eu criei</h2><small>${own.length}</small></div><div class="card-grid">${own.map(t=>`<article class="assign-card${taskActive(t)?'':' paused'}"><h3>${esc(t.data.title)}</h3><p class="assign-repeat">${icon(isPontual(t)?'clock':'repeat')}${esc(taskDesc(t))}</p><div class="assign-actions"><button class="text-btn" data-action="adm-task-edit" data-id="${t.id}">Editar</button><button class="text-btn" data-action="adm-task-pause" data-id="${t.id}">${taskActive(t)?'Pausar':'Retomar'}</button><button class="text-btn danger-text" data-action="adm-task-del" data-id="${t.id}">Excluir</button></div></article>`).join('')}</div>`:''}`}
// Gestão: vê o cronograma de todos, com o resumo de cada pessoa (feitas, pendentes e atrasadas) e filtro por pessoa.
function personTasks(id,d){const list=tasksOn(d,id).filter(t=>!lateP(t,d)),done=list.filter(t=>doneOf(t.id,d)).length,late=d===today()?lateTasks(id).length+pontualLate(id).length:0;return {list,done,pend:list.length-done,late}}
function oTasksManager(){const d=view.admDay||today(),all=admOf('tarefa').filter(t=>!pontualDone(t)).sort((a,b)=>String(a.data.title).localeCompare(b.data.title,'pt-BR')),people=taskPeople().filter(p=>p.role!=='gestor'||admOf('tarefa').some(t=>(t.data.assignees||[]).includes(p.id))),who=view.taskPerson&&people.some(p=>p.id===view.taskPerson)?view.taskPerson:null,shown=who?people.filter(p=>p.id===who):people,orphan=tasksOn(d).filter(t=>!(t.data.assignees||[]).some(id=>people.some(p=>p.id===id)));
 const stats=people.map(p=>({p,...personTasks(p.id,d)})),lateRows=d===today()?shown.flatMap(p=>[...lateTasks(p.id).map(x=>({...x,p})),...pontualLate(p.id).map(t=>({t,d:t.data.due,p}))]):[];
 return sectorTabs('adm')+pageHead('Administrativo','Cronograma','As tarefas de todo o administrativo. As assistentes veem as do dia umas das outras para cobrir atestado e folga, e podem transferir no dia.',headBtn('adm-task-new','Nova tarefa'))+admNotice()+`
 <div class="day-switch"><button class="icon-btn" data-action="adm-day" data-step="-1" aria-label="Dia anterior">${icon('back')}</button><strong>${d===today()?'Hoje':esc(longDate(d).replace(/^./,c=>c.toUpperCase()))}</strong><button class="icon-btn" data-action="adm-day" data-step="1" aria-label="Próximo dia">${icon('chevron')}</button></div>
 ${people.length?`<div class="people-sum">${stats.map(x=>`<button class="ps-card${who===x.p.id?' on':''}${x.late?' late':''}" data-action="adm-task-person" data-id="${x.p.id}" aria-pressed="${who===x.p.id}"><span class="pick-avatar sm">${esc(initials(x.p.name))}</span><span class="grow"><strong>${esc(shortName(x.p.name))}</strong><small>${esc(ROLE_NAMES[x.p.role])}</small></span><span class="ps-nums"><b>${x.done}/${x.list.length}</b><small>feitas</small></span>${x.late?`<span class="ps-late">${x.late} ${x.late===1?'atrasada':'atrasadas'}</span>`:''}</button>`).join('')}</div>${who?`<button class="text-btn" data-action="adm-task-person" data-id="">${icon('users')}Ver todos</button>`:''}`:`<div class="empty">${icon('users')}Ninguém do administrativo cadastrado.</div>`}
 ${lateRows.length?`<div class="section-title"><h2>Atrasadas</h2><small>${lateRows.length}</small></div><div class="adm-list">${lateRows.map(x=>admTaskRow(x.t,isPontual(x.t)?today():x.d,!who)).join('')}</div>`:''}
 ${shown.map(p=>{const x=personTasks(p.id,d);return x.list.length?`<div class="section-title"><h2>${esc(p.name)}</h2><small>${x.done} de ${x.list.length} feitas</small></div><div class="adm-list">${x.list.map(t=>admTaskRow(t,d,false,p.id)).join('')}</div>`:''}).join('')}
 ${!who&&orphan.length?`<div class="section-title"><h2>Sem responsável</h2></div><div class="adm-list">${orphan.map(t=>admTaskRow(t,d)).join('')}</div>`:''}
 ${!shown.some(p=>tasksOn(d,p.id).length)?`<div class="empty">${icon('sparkles')}Nenhuma tarefa ${d===today()?'para hoje':'neste dia'}${who?' para esta pessoa':''}.</div>`:''}
 <div class="section-title"><h2>Todas as tarefas${who?' de '+esc(shortName(people.find(p=>p.id===who).name)):''}</h2><small>${all.filter(t=>!who||(t.data.assignees||[]).includes(who)).length}</small></div>${all.length?`<div class="card-grid">${all.filter(t=>!who||(t.data.assignees||[]).includes(who)).map(t=>`<article class="assign-card${taskActive(t)?'':' paused'}"><h3>${esc(t.data.title)}</h3><p class="assign-repeat">${icon(isPontual(t)?'clock':'repeat')}${esc(taskDesc(t))}${isPontual(t)&&doneOf(t.id,today())?' · concluída':''}</p><p class="assign-text">${icon('users')} ${esc(assigneeNames(t))}${officePeople().some(p=>p.id===t.created_by)?` · criada por ${esc(shortName(t.created_by_name))}`:''}</p>${t.data.notes?`<p class="assign-text">${esc(t.data.notes)}</p>`:''}${taskActive(t)?'':'<div class="chip-row"><span class="chip warn">Pausada</span></div>'}<div class="assign-actions"><button class="text-btn" data-action="adm-task-edit" data-id="${t.id}">Editar</button><button class="text-btn" data-action="adm-task-pause" data-id="${t.id}">${taskActive(t)?'Pausar':'Retomar'}</button><button class="text-btn danger-text" data-action="adm-task-del" data-id="${t.id}">Excluir</button></div></article>`).join('')}</div>`:`<div class="empty">${icon('tasks')}Crie a primeira tarefa em “Nova tarefa”: checklist da sala, rasgar caixas, conferências…</div>`}`}
function admTaskDialog(t){const self=!isManager(),x=t?.data||{repeat:{type:'daily',every:1},start:today(),assignees:self?[authId]:[]},people=taskPeople();
 openModal(modalHead(t?'Editar tarefa':'Nova tarefa')+`<form id="adm-form" data-kind="tarefa" data-id="${t?.id||''}" autocomplete="off"><label class="field"><span>Tarefa</span><input name="title" required maxlength="120" value="${esc(x.title||'')}" placeholder="Ex.: Enviar o checklist da sala"></label><label class="field"><span>Como fazer <em>(opcional)</em></span><textarea name="notes" rows="2" maxlength="500">${esc(x.notes||'')}</textarea></label>
 ${self?`<input type="hidden" name="assignees" value="${authId}">`:`<div class="field"><span>Quem faz <em>(escolha uma ou mais pessoas)</em></span>${people.length?`<div class="who-pick">${[['contratos','Assistentes de contratos'],['analista','Analistas'],['gestor','Gestão']].map(([r,l])=>{const g=people.filter(p=>p.role===r);return g.length?`<p class="who-group">${l}</p><div class="who-chips">${g.map(p=>`<label class="who-chip"><input type="checkbox" name="assignees" value="${p.id}" ${(x.assignees||[]).includes(p.id)?'checked':''}><span>${icon('check')}${esc(p.name)}</span></label>`).join('')}</div>`:''}).join('')}<button type="button" class="text-btn" data-action="adm-assign-all">Marcar todos</button></div><p class="micro">Com mais de uma pessoa, quando uma concluir, a tarefa fica concluída para todas, com o nome de quem fez.</p>`:'<p class="micro">Ninguém cadastrado ainda. Cadastre em Pessoas.</p>'}</div>`}
 <div class="field"><span>Tipo de tarefa</span><div class="role-pick"><label class="radio-card"><input type="radio" name="tmode" value="agenda" ${x.mode!=='pontual'?'checked':''}><span><strong>Com data</strong><small>Uma vez só ou repetindo, com a frequência que quiser</small></span></label><label class="radio-card"><input type="radio" name="tmode" value="pontual" ${x.mode==='pontual'?'checked':''}><span><strong>Pontual</strong><small>Fica na lista até alguém concluir</small></span></label></div></div>
 <fieldset id="t-agenda" class="plain" ${x.mode==='pontual'?'hidden disabled':''}>${repeatWrap(x.repeat||{type:'daily',every:1},x.start||today(),x.end,true)}</fieldset><fieldset id="t-pontual" class="plain" ${x.mode==='pontual'?'':'hidden disabled'}>${dateInput('due',x.due,'Prazo <em>(opcional)</em>')}</fieldset><p class="form-error" role="alert"></p><button class="button" type="submit">Salvar</button></form>`)}
async function toggleDone(task,d){const f=doneOf(task,d);if(f){if(!(isManager()||f.created_by===authId))return;if(await admRemove(f.id))render();return}const t=admById(task);if(!t)return;const r=await admSave('tarefa_feita',{task,date:isPontual(t)?today():d,title:t.data.title});if(r){navigator.vibrate?.(15);render();toast('Tarefa feita ✓')}}

/* ---------- Chamados ---------- */
const ticketsOpen=()=>admOf('chamado').filter(x=>x.data.status!=='feito').sort((a,b)=>String(a.data.openedAt).localeCompare(String(b.data.openedAt)));
const ticketsDone=()=>admOf('chamado').filter(x=>x.data.status==='feito').sort((a,b)=>String(b.data.doneAt||'').localeCompare(String(a.data.doneAt||'')));
function oTickets(){const tab=view.ticketTab||'open',open=ticketsOpen(),done=ticketsDone(),list=tab==='open'?open:done.slice(0,60);
 return (isManager()?sectorTabs('adm'):'')+pageHead('Administrativo','Chamados','Registre o número e a data de cada chamado aberto e acompanhe até finalizar.',`<div class="head-actions"><button class="button compact outline head-action" data-action="adm-ticket-copy">${icon('copy')}Copiar</button>${headBtn('adm-ticket-new','Registrar chamado')}</div>`)+admNotice()+`
 <div class="area-tabs" role="tablist"><button role="tab" aria-selected="${tab==='open'}" class="${tab==='open'?'active':''}" data-action="adm-ticket-tab" data-tab="open">Em aberto <small>${open.length}</small></button><button role="tab" aria-selected="${tab==='done'}" class="${tab==='done'?'active':''}" data-action="adm-ticket-tab" data-tab="done">Finalizados <small>${done.length}</small></button></div>
 ${list.length?`<div class="card-grid">${list.map(x=>`<article class="assign-card ticket${x.data.status==='feito'?' done':''}"><div class="ticket-top"><strong>Nº ${esc(x.data.number)}</strong>${x.data.status==='feito'?`<span class="chip done">Feito ${dateBR(x.data.doneAt)}</span>`:`<span class="chip warn">Aberto ${daysAgo(x.data.openedAt)}</span>`}</div><p class="assign-text">${esc(x.data.description||'')}</p><p class="micro">Aberto em ${dateBR(x.data.openedAt)} · registrado por ${esc(shortName(x.created_by_name))}${x.data.status==='feito'&&x.data.doneBy?` · finalizado por ${esc(shortName(x.data.doneBy))}`:''}</p>${doneCheck(x)}<div class="assign-actions"><button class="text-btn" data-action="adm-ticket-edit" data-id="${x.id}">Editar</button><button class="text-btn" data-action="adm-history" data-id="${x.id}">Histórico</button><button class="text-btn danger-text" data-action="adm-ticket-del" data-id="${x.id}">Excluir</button></div></article>`).join('')}</div>`:`<div class="empty">${icon('ticket')}${tab==='open'?'Nenhum chamado em aberto.':'Nenhum chamado finalizado ainda.'}</div>`}`}
// Botão grande de concluir: caixa que marca com animação; feito, mostra quem e quando e permite reabrir.
function doneCheck(x){const on=x.data.status==='feito';return `<button class="done-check${on?' is-on':''}" data-action="adm-ticket-toggle" data-id="${x.id}" role="checkbox" aria-checked="${on}"><span class="dc-box" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span><span class="dc-text"><strong>${on?'Feito':'Marcar como feito'}</strong>${on?'<small>Toque para reabrir</small>':''}</span></button>`}
function ticketDialog(x){const d=x?.data||{openedAt:today()};openModal(modalHead(x?'Editar chamado':'Registrar chamado')+`<form id="adm-form" data-kind="chamado" data-id="${x?.id||''}" autocomplete="off"><div class="field-grid"><label class="field"><span>Número do chamado</span><input name="number" required maxlength="40" value="${esc(d.number||'')}" placeholder="Ex.: 123456"></label>${dateInput('openedAt',d.openedAt,'Aberto em',true)}</div><label class="field"><span>Descrição</span><textarea name="description" rows="3" required maxlength="800" placeholder="O que foi pedido no chamado">${esc(d.description||'')}</textarea></label><p class="form-error" role="alert"></p><button class="button" type="submit">Salvar</button></form>`)}
// Modelo da sala: descrição e, embaixo, "(Chamado aberto #número aberto dia dd/mm/aaaa)", um bloco por chamado em aberto.
function ticketCopyText(){return ticketsOpen().map(x=>`${String(x.data.description||'').trim()}\n(Chamado aberto #${String(x.data.number).replace(/^#/,'')} aberto dia ${dateBR(x.data.openedAt)})`).join('\n\n')}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch(e){const t=document.createElement('textarea');t.value=text;t.setAttribute('readonly','');t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch(x){}t.remove();return ok}}

/* ---------- Notas fiscais (parceiros e alimentação PJ) ---------- */
const NOTE_TYPES=[['parceiro','Parceiros'],['alimentacao','Alimentação PJ']];
const NOTE_STEPS=[['recebida','Nota recebida'],['vouchers','Baixa nos vouchers'],['zeev','Lançada no Zeev'],['pagamento','Pagamento']];
// Um parceiro pode ser dos dois tipos (parceiro e alimentação PJ): cada tipo tem a própria nota no mês.
const partnerTypes=p=>Array.isArray(p?.data.types)&&p.data.types.length?p.data.types:[p?.data.type||'parceiro'];
const noteType=n=>n.data.type||partnerTypes(admById(n.data.partner))[0];
const partnersOf=t=>admOf('parceiro').filter(p=>partnerTypes(p).includes(t)).sort((a,b)=>String(a.data.name).localeCompare(b.data.name,'pt-BR'));
// Um parceiro pode mandar mais de uma nota no mês: cada nota é um registro com as próprias etapas.
const notesOf=(partner,m,t)=>admOf('nota').filter(n=>n.data.partner===partner&&n.data.month===m&&(!t||noteType(n)===t)).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at)));
const noteOf=(partner,m,t)=>notesOf(partner,m,t)[0];
// Parceiro vale a partir do mês em que foi cadastrado até o mês em que saiu da lista (o histórico anterior fica).
const partnerFrom=p=>p.data.since||spDay(p.created_at).slice(0,7)||'0000-00';
const partnerInMonth=(p,m)=>m>=partnerFrom(p)&&(!p.data.inactiveFrom||m<p.data.inactiveFrom);
const partnersIn=(t,m)=>partnersOf(t).filter(p=>partnerInMonth(p,m)||noteOf(p.id,m,t));
// Nota: recebida (data) ou "sem nota este mês" (decidido). Vouchers chegam todo mês: baixa ou "não entregou" (vira cobrança).
const voucherMissing=n=>!!n?.data.steps?.vouchers?.missing;
const noteNone=n=>!!n?.data.steps?.recebida?.none;
const notePending=n=>!n?.data.steps?.recebida?.date&&!noteNone(n);
// Nota recebida com problema (valor errado, dados errados…): continua pendente até ser resolvida.
const noteProblem=n=>!!n?.data.problem&&!n.data.problem.resolved;
const noteLaunched=n=>!!n?.data.steps?.zeev?.date;
// Situação do parceiro no mês somando as notas: pendente até chegar a primeira (ou se alguma registrada ainda não chegou).
function partnerMonth(p,m,t){const ns=notesOf(p.id,m,t),real=ns.filter(n=>!noteNone(n)),none=!real.length&&ns.some(noteNone);
 return {ns,real,none,pending:!none&&(!real.length||real.some(notePending)),problem:real.some(noteProblem),launched:real.length>0&&real.every(noteLaunched),received:real.filter(n=>n.data.steps?.recebida?.date).length}}
const noteLabel=(n,i,total)=>total>1?(n.data.number?`nota nº ${n.data.number}`:`${i+1}ª nota`):'nota';
const pendingPartners=(m=today().slice(0,7))=>NOTE_TYPES.flatMap(([t])=>partnersIn(t,m).filter(p=>{const x=partnerMonth(p,m,t);return x.pending||x.problem}));
function noteStatus(n){const s=n?.data.steps||{},pill=(ok,cls,txt)=>`<span class="step-pill${cls}">${ok?icon('check'):''}${txt}</span>`,d=x=>x?' '+shortDate(x):'';
 if(noteNone(n))return pill(false,' muted-pill','Sem nota no mês');
 return [noteNone(n)?pill(false,' muted-pill','Sem nota no mês'):noteProblem(n)?pill(false,' warn-pill','Nota com problema'):pill(!!s.recebida?.date,s.recebida?.date?' ok':' bad',s.recebida?.date?`Nota${d(s.recebida.date)}`:'Pendente de receber'),voucherMissing(n)?pill(false,' bad','Voucher não entregue'):pill(!!s.vouchers?.date,s.vouchers?.date?' ok':'',`Vouchers${d(s.vouchers?.date)}`),pill(!!s.zeev?.date,s.zeev?.date?' ok':'',s.zeev?.date?`Lançada${d(s.zeev.date)}`:'Lançamento no Zeev'),s.pagamento?.date?pill(!!s.pagamento.done,s.pagamento.done?' ok':'',s.pagamento.done?`Pago${d(s.pagamento.date)}`:`Pagar${d(s.pagamento.date)}`):''].join('')}
// O que falta cobrar no mês: nota ainda pendente ou voucher sem baixa (inclusive o marcado como não entregue).
function noteCharges(t,m){return partnersIn(t,m).filter(p=>partnerInMonth(p,m)).map(p=>{const x=partnerMonth(p,m,t),miss=[];if(x.none)return {p,miss};if(!x.real.length){miss.push('nota fiscal');miss.push('voucher');return {p,miss}}
 x.real.forEach((n,i)=>{const s=n.data.steps||{},lb=noteLabel(n,i,x.real.length),of=x.real.length>1?` (${lb})`:'';if(notePending(n))miss.push('nota fiscal'+of);if(noteProblem(n))miss.push(`correção da ${lb} (${n.data.problem.text||'problema na nota'})`);if(voucherMissing(n))miss.push(`voucher${of} (não entregou${s.vouchers.reason?': '+s.vouchers.reason:''})`);else if(!s.vouchers?.date)miss.push('voucher'+of)});return {p,miss}}).filter(x=>x.miss.length)}
const chargeText=(t,m)=>[`*Cobrança — ${t==='alimentacao'?'Alimentação PJ':'Parceiros'} — ${monthLabel(m)}*`,'',...noteCharges(t,m).map(x=>`• ${x.p.data.name}: falta ${x.miss.join(' e ')}`)].join('\n');
// Resumo do mês (gestão e analista): notas recebidas, lançadas, pagas, valores.
function noteSummary(t,m){const ps=partnersIn(t,m),xs=ps.map(p=>partnerMonth(p,m,t)),c=f=>xs.filter(f).length;return {total:ps.length,due:ps.length-c(x=>x.none),pend:c(x=>x.pending),prob:c(x=>x.problem),launched:c(x=>x.launched),none:c(x=>x.none),noVoucher:c(x=>x.real.some(voucherMissing)),notes:xs.reduce((a,x)=>a+x.received,0)}}
function noteSummaryHtml(m){const pct=(a,b)=>b?Math.round(a/b*100):0;return `<div class="note-sum">${NOTE_TYPES.map(([t,l])=>{const x=noteSummary(t,m);if(!x.total)return '';return `<div class="note-sum-card"><strong>${l}</strong><div class="note-sum-row">${[['Pendentes de receber',x.pend,x.due,'bad'],['Pendentes com problema',x.prob,x.due,'warn'],['Lançadas no Zeev',x.launched,x.due,'ok']].map(([lb,a,b,cls])=>`<div class="ns-${cls}"><small>${lb}</small><b>${a}<em>/${b}</em></b><span class="dash-bar"><i style="width:${pct(a,b)}%"></i></span><span class="pct">${pct(a,b)}%</span></div>`).join('')}</div>${x.noVoucher||x.none?`<p class="note-sum-foot">${x.noVoucher?`<span class="late-text">${plural(x.noVoucher,'voucher não entregue','vouchers não entregues')}</span>`:''}${x.none?`<span>${plural(x.none,'parceiro sem nota no mês','parceiros sem nota no mês')}</span>`:''}</p>`:''}</div>`}).join('')}</div>`}
// Linha do parceiro: uma linha por nota do mês e, depois da primeira recebida, o botão para lançar outra.
function noteLine(p,t,m,n,i,total){const name=`${esc(p.data.name)}${total>1?` <small class="note-no">· ${esc(noteLabel(n,i,total))}</small>`:''}${partnerInMonth(p,m)?'':' <small class="muted">· saiu da lista</small>'}`;
 return `<button class="note-row" data-action="adm-note" data-partner="${p.id}" data-type="${t}" data-note="${n?.id||''}"><span class="grow"><strong>${name}</strong><span class="step-row">${noteStatus(n)}</span>${noteProblem(n)&&n.data.problem?.text?`<small class="late-text">${esc(n.data.problem.text)}</small>`:''}${n?.data.number||n?.data.value||n?.data.log?.length?`<small>${[total<2&&n.data.number?'Nota '+esc(n.data.number):'',n.data.value?brl(n.data.value):'',n.data.log?.length?`última ação: ${esc(shortName(n.data.log.at(-1).by))}, ${dateBR(n.data.log.at(-1).at)}`:''].filter(Boolean).join(' · ')}</small>`:''}</span>${icon('chevron','chevron')}</button>`}
function noteGroup(p,t,m){const x=partnerMonth(p,m,t),ns=x.ns.length?x.ns:[null];return `<div class="note-group${ns.length>1?' multi':''}">${ns.map((n,i)=>noteLine(p,t,m,n,i,ns.length)).join('')}${x.received&&!x.none?`<button class="note-add" data-action="adm-note-new" data-partner="${p.id}" data-type="${t}">${icon('plus')}Outra nota deste parceiro</button>`:''}</div>`}
function oNotes(){const t=view.noteType||'parceiro',m=view.noteMonth||today().slice(0,7),ps=partnersIn(t,m),ch=noteCharges(t,m);
 return (isManager()?sectorTabs('adm'):'')+pageHead('Administrativo','Notas fiscais','Uma linha por parceiro em cada mês: nota recebida (ou com problema), baixa nos vouchers e lançamento no Zeev.',`<button class="button compact outline head-action" data-action="o-partners">${icon('users')}Parceiros</button>`)+admNotice()+`
 ${monthNav(m,'adm-note-month')}
 ${ps.length?`<div class="charge-bar${ch.length?'':' ok'}">${icon(ch.length?'info':'check')}<span class="grow">${ch.length?`<strong>Pendentes em ${monthLabel(m).split(' ')[0].toLowerCase()}</strong> · ${plural(ch.length,'parceiro','parceiros')}`:'<strong>Nada pendente</strong> neste mês'}</span>${ch.length?`<button class="button compact outline" data-action="adm-note-charge">${icon('copy')}Copiar cobrança</button>`:''}</div>`:''}
 ${noteSummaryHtml(m)}
 <div class="area-tabs" role="tablist">${NOTE_TYPES.map(([k,l])=>`<button role="tab" aria-selected="${t===k}" class="${t===k?'active':''}" data-action="adm-note-type" data-type="${k}">${l} <small>${partnersIn(k,m).length}</small></button>`).join('')}</div>
 ${ps.length?`
 <div class="adm-list">${ps.map(p=>noteGroup(p,t,m)).join('')}</div>`
 :`<div class="empty">${icon('users')}Nenhum ${t==='parceiro'?'parceiro':'fornecedor de alimentação PJ'} neste mês. Toque em “Parceiros” para cadastrar.</div>`}`}
// Etapa da nota: marca com um toque; a data (hoje) aparece só depois de marcar e pode ser trocada.
const nStep=(k,label,date)=>`<div class="nstep${date?' on':''}"><label class="nstep-head"><input type="checkbox" data-step="${k}" ${date?'checked':''}><span class="dc-box" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span><strong>${label}</strong></label><input type="date" name="${k}" value="${esc(date||'')}" aria-label="Data: ${label}" ${date?'':'hidden'}></div>`;
document.addEventListener('change',e=>{const c=e.target;if(!(c instanceof HTMLInputElement))return;
 if(c.dataset.step){const box=c.closest('.nstep'),d=box.querySelector('input[type=date]');box.classList.toggle('on',c.checked);d.hidden=!c.checked;d.value=c.checked?(d.value||today()):''}
 if(c.dataset.reveal){const el=document.getElementById(c.dataset.reveal);if(el)el.hidden=!c.checked}});
function noteDialog(partnerId,t,noteId,isNew){const p=admById(partnerId);t=t||partnerTypes(p)[0];const m=view.noteMonth||today().slice(0,7),all=notesOf(partnerId,m,t),n=isNew?null:(noteId&&admById(noteId))||all[0],pos=n?all.indexOf(n):all.length,total=Math.max(all.length,pos+1),others=all.filter(x=>x!==n),d=n?.data||{steps:{}},s=d.steps||{},log=(d.log||[]).slice().reverse();
 openModal(modalHead(esc(p?.data.name||'Nota'))+`<p class="subtitle">${monthLabel(m)} · ${t==='alimentacao'?'Alimentação PJ':'Parceiro'}${total>1?` · ${pos+1}ª nota do mês`:''}</p><form id="adm-form" data-kind="nota" data-id="${n?.id||''}" data-partner="${partnerId}" data-type="${t}" data-month="${m}" autocomplete="off">
 <div class="nsteps">${nStep('recebida','Nota recebida',s.recebida?.date)}${nStep('vouchers','Baixa nos vouchers',s.vouchers?.date)}${nStep('zeev','Lançada no Zeev',s.zeev?.date)}</div>
 <details class="nmore"${noteProblem(n)||s.recebida?.none?' open':''}><summary>Algum problema?<small>nota com problema${others.length?'':' · sem nota'}</small></summary>
  <label class="check-row"><input type="checkbox" name="problem" data-reveal="problemBox" ${noteProblem(n)?'checked':''}><span>Nota com problema<small>Fica pendente até desmarcar.</small></span></label>
  <label class="field" id="problemBox" ${noteProblem(n)?'':'hidden'}><span>Qual o problema?</span><input name="problemText" maxlength="300" value="${esc(d.problem?.text||'')}" placeholder="Ex.: valor errado"></label>
  ${others.length?'':`<label class="check-row"><input type="checkbox" name="noteNone" ${s.recebida?.none?'checked':''}><span>Sem nota este mês</span></label>`}
  <label class="field"><span>Motivo <em>(opcional)</em></span><input name="voucherReason" maxlength="200" value="${esc(s.vouchers?.reason||s.recebida?.reason||'')}"></label>
 </details>
 <details class="nmore"${d.number||d.value||s.pagamento?.date||d.obs?' open':''}><summary>Mais detalhes<small>nº, valor, pagamento, observação</small></summary>
  <div class="field-grid"><label class="field"><span>Nº da nota</span><input name="number" maxlength="40" value="${esc(d.number||'')}"></label>${moneyInput('value',d.value,'Valor',false)}</div>
  <div class="field-grid">${dateInput('pagamento',s.pagamento?.date,'Pagamento previsto')}<label class="check-row nm-paid"><input type="checkbox" name="paid" ${s.pagamento?.done?'checked':''}><span>Pagamento efetivado</span></label></div>
  <label class="field"><span>Observação</span><textarea name="obs" rows="2" maxlength="500">${esc(d.obs||'')}</textarea></label>
 </details>
 <p class="form-error" role="alert"></p><button class="button" type="submit">Salvar</button></form>
 ${log.length?`<div class="section-title"><h2>Histórico</h2><small>${log.length}</small></div><div class="history">${log.map(h=>`<p><span>${esc(h.text)}</span><small>${esc(h.by)} · ${dateBR(h.at)} às ${timeOf(h.at)}</small></p>`).join('')}</div>`:''}
 ${n&&(isManager()||n.created_by===authId)?`<button class="small-link danger-text" data-action="adm-note-del" data-id="${n.id}">${total>1?'Apagar esta nota':'Apagar o registro deste mês'}</button>`:''}`)}
function oPartners(){const t=view.noteType||'parceiro',m=today().slice(0,7);return `${backLabel('Notas fiscais')}`+pageHead('Administrativo','Parceiros','Cadastro dos parceiros e das empresas de alimentação PJ que mandam nota todo mês.',headBtn('adm-partner-new','Novo parceiro'))+admNotice()+`
 <div class="area-tabs" role="tablist">${NOTE_TYPES.map(([k,l])=>`<button role="tab" aria-selected="${t===k}" class="${t===k?'active':''}" data-action="adm-note-type" data-type="${k}">${l} <small>${partnersOf(k).filter(p=>partnerInMonth(p,m)).length}</small></button>`).join('')}</div>
 ${partnersOf(t).length?`<div class="item-list">${partnersOf(t).map(p=>`<div class="item-row"><strong>${esc(p.data.name)}${!partnerInMonth(p,m)?` <small class="muted">· ${p.data.inactiveFrom?'saiu da lista em '+monthLabel(p.data.inactiveFrom).toLowerCase():'a partir de '+monthLabel(partnerFrom(p)).toLowerCase()}</small>`:''}${p.data.info?`<small class="muted block">${esc(p.data.info)}</small>`:''}</strong><div class="item-actions"><button class="icon-btn" data-action="adm-partner-edit" data-id="${p.id}" aria-label="Editar ${esc(p.data.name)}">${icon('edit')}</button>${admOf('nota').some(n=>n.data.partner===p.id)?'':`<button class="icon-btn danger" data-action="adm-partner-del" data-id="${p.id}" aria-label="Excluir ${esc(p.data.name)}">${icon('trash')}</button>`}</div></div>`).join('')}</div><p class="bottom-note">Quem já tem notas registradas não é excluído: em Editar, tire da lista a partir de um mês. Os meses anteriores continuam com o histórico.</p>`:`<div class="empty">${icon('users')}Nenhum cadastrado ainda.</div>`}`}
function partnerDialog(x){const d=x?.data||{type:view.noteType||'parceiro'},m=today().slice(0,7);openModal(modalHead(x?'Editar parceiro':'Novo parceiro')+`<form id="adm-form" data-kind="parceiro" data-id="${x?.id||''}" autocomplete="off"><label class="field"><span>Nome</span><input name="name" required maxlength="100" value="${esc(d.name||'')}"></label><div class="field"><span>Tipo <em>(pode marcar os dois)</em></span><div class="who-chips">${NOTE_TYPES.map(([k,l])=>`<label class="who-chip"><input type="checkbox" name="types" value="${k}" ${(x?partnerTypes(x):[view.noteType||'parceiro']).includes(k)?'checked':''}><span>${icon('check')}${k==='parceiro'?'Parceiro':l}</span></label>`).join('')}</div></div><label class="field"><span>Contato ou observação <em>(opcional)</em></span><input name="info" maxlength="200" value="${esc(d.info||'')}"></label>
 <div class="field-grid"><label class="field"><span>Na lista a partir de</span><input name="since" type="month" required value="${esc(x?partnerFrom(x):m)}"></label><label class="field"><span>Sai da lista em <em>(opcional)</em></span><input name="inactiveFrom" type="month" value="${esc(d.inactiveFrom||'')}"></label></div><p class="micro">Ao sair da lista, o parceiro deixa de ser cobrado a partir daquele mês. Os meses anteriores ficam com o histórico.</p><p class="form-error" role="alert"></p><button class="button" type="submit">Salvar</button></form>`)}

/* ---------- Pedidos mensais ---------- */
const orders=()=>admOf('pedido').sort((a,b)=>String(b.data.month).localeCompare(a.data.month)||String(b.created_at).localeCompare(a.created_at));
const openOrders=()=>admOf('pedido').filter(o=>o.data.status==='nao_conforme'&&!o.data.resolved);
const orderChip=o=>o.data.resolved?'<span class="chip done">Resolvido</span>':o.data.status==='nao_conforme'?'<span class="chip late">Com pendência</span>':o.data.status==='conforme'?'<span class="chip done">Conforme</span>':'<span class="chip">Aguardando conferência</span>';
const orderName=o=>o.data.supplier?`${o.data.supplier}`:o.data.title||'Pedido de '+monthLabel(o.data.month).toLowerCase();
const orderSteps=o=>`<span class="step-row">${[['arrivedAt','Pedido'],['invoiceAt','Nota'],['zeevAt','Zeev'],['payAt','Pagamento']].map(([k,l])=>`<span class="step-pill${o.data[k]?' ok':''}">${o.data[k]?icon('check'):''}${l}${o.data[k]?' '+shortDate(o.data[k]):''}</span>`).join('')}</span>`;
// Pedidos entram no mês em que chegaram (ou no mês do pedido, enquanto não chegam).
const orderMonth=o=>String(o.data.arrivedAt||'').slice(0,7)||o.data.month;
function oOrders(){const m=view.orderMonth||today().slice(0,7),list=orders().filter(o=>orderMonth(o)===m),arrived=list.filter(o=>o.data.arrivedAt),c=f=>arrived.filter(f).length,nc=arrived.filter(o=>o.data.status==='nao_conforme');
 return (isManager()?sectorTabs('adm'):'')+pageHead('Administrativo','Pedidos','Pedido mensal ao setor de compras: quando chegaram o pedido e a nota, o lançamento no Zeev, o pagamento programado e a conferência.',headBtn('adm-order-new','Registrar pedido'))+admNotice()+`
 ${monthNav(m,'adm-order-month')}
 <div class="order-sum"><div><small>Chegaram no mês</small><b>${arrived.length}</b>${list.length>arrived.length?`<span>${plural(list.length-arrived.length,'ainda não chegou','ainda não chegaram')}</span>`:''}</div><div><small>Conformes</small><b class="ok-text">${c(o=>o.data.status==='conforme')}</b></div><div><small>Não conformes</small><b class="${nc.some(o=>!o.data.resolved)?'late-text':''}">${nc.length}</b><span>${nc.filter(o=>o.data.resolved).length} resolvidos · ${nc.filter(o=>!o.data.resolved).length} em aberto</span></div><div><small>Nota recebida</small><b>${c(o=>o.data.invoiceAt)}/${arrived.length}</b></div><div><small>Lançados no Zeev</small><b>${c(o=>o.data.zeevAt)}/${arrived.length}</b></div><div><small>Pagamento programado</small><b>${c(o=>o.data.payAt)}/${arrived.length}</b>${arrived.filter(o=>o.data.payAt).length?`<span>${arrived.filter(o=>o.data.payAt).map(o=>dateBR(o.data.payAt)).join(', ')}</span>`:''}</div></div>
 ${list.length?`<div class="adm-list">${list.map(o=>`<button class="note-row" data-action="o-order" data-id="${o.id}"><span class="grow"><strong>${esc(orderName(o))}</strong>${orderSteps(o)}<small>${orderChip(o)}${(o.data.comments||[]).filter(x=>!x.sys).length?` · ${plural(o.data.comments.filter(x=>!x.sys).length,'comentário','comentários')}`:''}</small></span>${icon('chevron','chevron')}</button>`).join('')}</div>`:`<div class="empty">${icon('truck')}Nenhum pedido em ${monthLabel(m).toLowerCase()}. Quando o pedido chegar, toque em “Registrar pedido”.</div>`}`}
// Registro do pedido: só o que se sabe na chegada. Nota (se não veio junto), Zeev e pagamento entram depois, na tela do pedido.
