const unpaidPays=()=>admOf('pagamento').filter(p=>!p.data.cancelled&&!payPaid(p));
const paysOf=(caixa,m,all)=>admOf('pagamento').filter(p=>p.data.caixa===caixa&&p.data.month===m&&(all||!p.data.cancelled)).sort((a,b)=>String(b.data.date).localeCompare(a.data.date)||String(b.created_at).localeCompare(a.created_at));
function cashSummary(c,m){const teams=c.data.teams||[],ps=paysOf(c.id,m),budget=teams.reduce((s,t)=>s+Number(t.amount||0),0),spent=ps.reduce((s,p)=>s+Number(p.data.value||0),0);
 return {budget,spent,left:Math.round((budget-spent)*100)/100,teams:teams.map(t=>{const sp=ps.filter(p=>p.data.team===t.id).reduce((s,p)=>s+Number(p.data.value||0),0);return {...t,spent:sp,left:Math.round((Number(t.amount||0)-sp)*100)/100}}),ps}}
