 const c=list.find(x=>x.id===view.cash)||list[0],s=cashSummary(c,m),teams=s.teams,multi=teams.length>1,pc=s.budget?Math.min(100,Math.round(s.spent/s.budget*100)):0,tf=multi&&teams.some(t=>t.id===view.cashTeam)?view.cashTeam:'',shown=tf?s.ps.filter(p=>p.data.team===tf):s.ps,tSel=teams.find(t=>t.id===tf);
