function printReceipt(p){const w=window.open('','_blank');if(!w){toast('Libere as janelas do navegador para imprimir o recibo.');return}w.document.write(receiptHtml(p));w.document.close();const c=admById(p.data.caixa);if(!c?.data.payer||!c?.data.payerDoc||!c?.data.city)toast('O recibo saiu com campos em branco: configure quem paga, o CPF/CNPJ e a cidade em Caixas → Configurar.')}
