 const row=p=>`<tr><td>${dateBR(p.data.date)}</td><td><b>${esc(p.data.recipient)}</b>${p.data.recipientDoc?`<br><small>${esc(docMask(p.data.recipientDoc))}</small>`:''}</td><td>${esc(p.data.action||'')}</td><td>${payLaunched(p)?(payLaunched(p).date?dateBR(payLaunched(p).date):'Sim'):'—'}</td><td>${payPaid(p)?(payPaid(p).date?dateBR(payPaid(p).date):'Sim'):'—'}</td><td>${esc(shortName(p.created_by_name||''))}</td><td class="r">${brl(p.data.value)}</td></tr>`;
