const LEVELS={ok:['Verde','Tudo certo'],medio:['Amarelo','Erro mediano, talvez não venha'],grave:['Vermelho','Erro que vai ou corre risco de vir'],na:['Não se aplica','']};
const LEVEL_RANK={grave:3,medio:2,ok:1,na:0};
const contractLevel=c=>{if(!c.data.audit)return 'pendente';let w='ok';for(const [k] of AUDIT_CHECKS){const l=c.data.checks?.[k]?.level;if(l&&LEVEL_RANK[l]>LEVEL_RANK[w])w=l}return w};
