function auditDialog(c){const d=c.data,ck=d.checks||{};
 openModal(modalHead('Auditar contrato')+`<p class="subtitle">${esc(d.cliente)} · ${dateBR(d.dataVenda)} · ${plural(Number(d.cotas||0),'cota','cotas')} · lançado por ${esc(d.lancamento?.name||'—')}</p><form id="adm-form" data-kind="contrato-auditoria" data-id="${c.id}" autocomplete="off">
 ${AUDIT_CHECKS.map(([k,lb])=>{const x=ck[k]||{level:'ok'},opts=['ok','medio','grave',...(k==='boletos'||k==='flow'?['na']:[])];return `<fieldset class="audit-check"><legend>${lb}</legend><div class="lv-pick">${opts.map(o=>`<label class="lv-opt lv-${o}"><input type="radio" name="lv-${k}" value="${o}" ${x.level===o?'checked':''}><span>${LEVELS[o][0]}</span></label>`).join('')}</div>${k==='boletos'?`<div class="quick-vals">${['OK','ONLINE'].map(v=>`<label><input type="radio" name="val-${k}" value="${v}" ${(x.value||'OK')===v?'checked':''}><span>${v}</span></label>`).join('')}</div>`:''}${k==='flow'?`<div class="quick-vals">${['SIM','NÃO - MANUAL'].map(v=>`<label><input type="radio" name="val-${k}" value="${v}" ${(x.value||'SIM')===v?'checked':''}><span>${v}</span></label>`).join('')}</div>`:''}<input name="note-${k}" maxlength="400" placeholder="Descreva o erro (obrigatório no amarelo e no vermelho)" value="${esc(x.note||'')}"></fieldset>`}).join('')}
 <p class="micro">Verde: tudo certo · Amarelo: erro mediano, talvez não venha · Vermelho: erro que vai ou corre muito risco de ser pontuado para a sala.</p>
 <p class="form-error" role="alert"></p><button class="button" type="submit">${icon('check')}Salvar auditoria</button></form>`)}
function exportContracts(){const m=view.contractMonth||today().slice(0,7),rows=contractsOf(m);if(!rows.length){toast('Nenhum contrato neste mês.');return}const cell=csvCell;
 const head=['CLIENTE','APROVADOR','DATA DA VENDA','TURNO','QUANT. COTAS','RESPONSÁVEL DO LANÇAMENTO','AUDITADO','DATA DA AUDITORIA','ERRO','BOLETOS','DOCUMENTAÇÃO UAU','CRM','FLOW','GRAVIDADE'];
 const csv=[head.map(cell).join(';'),...rows.map(c=>{const d=c.data,a=d.audit;return [d.cliente,d.aprovador,dateBR(d.dataVenda),d.turno||'',d.cotas,d.lancamento?.name,a?'SIM':'NÃO',a?dateBR(a.date):'',checkText(c,'erro'),checkText(c,'boletos'),checkText(c,'uau'),checkText(c,'crm'),checkText(c,'flow'),{pendente:'',ok:'VERDE',medio:'AMARELO',grave:'VERMELHO'}[contractLevel(c)]].map(cell).join(';')})].join('\r\n');
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'}));a.download=`auditoria-contratos-${m}.csv`;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);toast('Planilha do mês exportada.')}

document.addEventListener('input',e=>{if(e.target.id!=='contract-search')return;const pos=e.target.selectionStart;view.contractQuery=e.target.value;render();const f=document.getElementById('contract-search');if(f){f.focus();f.setSelectionRange(pos,pos)}});
// Logo do recibo (GAV Hotéis e Resorts, azul sobre branco), embutida para o recibo abrir em qualquer janela.
const RECEIPT_LOGO='data:image/jpeg;base64,';
document.addEventListener('change',e=>{if(e.target.name!=='tmode')return;const p=e.target.value==='pontual',a=document.getElementById('t-agenda'),b=document.getElementById('t-pontual');if(a){a.hidden=p;a.disabled=p}if(b){b.hidden=!p;b.disabled=!p}});

/* ---------- Painel de contratos da gestão (só para ver: não há ação sobre os erros) ---------- */
const LV_COLORS={ok:'#3f9a6e',medio:'#e0a526',grave:'#c8443d'};
const seenKey=(what='contratos')=>`gav-${what}-visto:${authId}`;
const contractsSeenAt=()=>{try{return localStorage.getItem(seenKey())||''}catch(e){return ''}};
function markContractsSeen(){if(!isManager())return;try{localStorage.setItem(seenKey(),new Date().toISOString())}catch(e){}}
// Chamados: a gestão só é avisada de chamado novo; o resto é acompanhamento.
const ticketsSeenAt=()=>{try{return localStorage.getItem(seenKey('chamados'))||''}catch(e){return ''}};
const newTickets=()=>{const seen=ticketsSeenAt();return admOf('chamado').filter(x=>String(x.created_at||'')>seen)};
function markTicketsSeen(){if(!isManager())return;try{localStorage.setItem(seenKey('chamados'),new Date().toISOString())}catch(e){}}
// Erros (amarelo/vermelho) auditados depois da última vez que a gestão abriu os contratos.
const newContractErrors=()=>{const seen=contractsSeenAt();return admOf('contrato').filter(c=>{const l=contractLevel(c);return (l==='grave'||l==='medio')&&String(c.updated_at||'')>seen})};
function contractDash(m){const cs=contractsOf(m),aud=cs.filter(c=>c.data.audit),k=l=>aud.filter(c=>contractLevel(c)===l).length,pct=n=>aud.length?Math.round(n/aud.length*100):0;
 const months=[...Array(6)].map((_,i)=>shiftMonth(m,i-5)),series=months.map(mm=>{const a=contractsOf(mm).filter(c=>c.data.audit);return {mm,ok:a.filter(c=>contractLevel(c)==='ok').length,medio:a.filter(c=>contractLevel(c)==='medio').length,grave:a.filter(c=>contractLevel(c)==='grave').length}});
 const max=Math.max(1,...series.map(x=>x.ok+x.medio+x.grave)),W=600,H=210,top=22,base=H-28,bw=46,step=W/6,y=v=>v/max*(base-top);
 const bars=series.map((x,i)=>{const cx=step*i+step/2,parts=[['ok',x.ok],['medio',x.medio],['grave',x.grave]].filter(p=>p[1]);let acc=0;const tot=x.ok+x.medio+x.grave,lbl=monthLabel(x.mm).split(' ')[0].slice(0,3);
  return parts.map(([l,v],j)=>{const h=y(v),r=`<rect x="${cx-bw/2}" y="${base-acc-h+(acc?2:0)}" width="${bw}" height="${Math.max(0,h-(acc?2:0))}" rx="${j===parts.length-1?4:0}" fill="${LV_COLORS[l]}"><title>${monthLabel(x.mm)}: ${v} ${LEVELS[l][0].toLowerCase()}${v===1?'':'s'}</title></rect>`;acc+=h;return r}).join('')+`<text x="${cx}" y="${base-acc-6}" text-anchor="middle" class="ch-val">${tot||''}</text><text x="${cx}" y="${H-8}" text-anchor="middle" class="ch-axis${x.mm===m?' cur':''}">${lbl}</text>`}).join('');
 const items=AUDIT_CHECKS.map(([kk,lb])=>({lb,medio:aud.filter(c=>c.data.checks?.[kk]?.level==='medio').length,grave:aud.filter(c=>c.data.checks?.[kk]?.level==='grave').length})),imax=Math.max(1,...items.map(x=>x.medio+x.grave));
 const people=[...new Set(cs.map(c=>c.data.lancamento?.name||'—'))].map(n=>{const a=aud.filter(c=>(c.data.lancamento?.name||'—')===n);return {n,total:cs.filter(c=>(c.data.lancamento?.name||'—')===n).length,ok:a.filter(c=>contractLevel(c)==='ok').length,medio:a.filter(c=>contractLevel(c)==='medio').length,grave:a.filter(c=>contractLevel(c)==='grave').length}}).sort((a,b)=>b.grave-a.grave||b.medio-a.medio||b.total-a.total);
 const recent=aud.filter(c=>['grave','medio'].includes(contractLevel(c))).sort((a,b)=>String(b.updated_at).localeCompare(a.updated_at)).slice(0,8);
 return `<section class="cdash"><div class="cdash-stats"><div><small>Contratos</small><strong>${cs.length}</strong><span>${cs.reduce((s,c)=>s+Number(c.data.cotas||0),0)} cotas · ${aud.length} auditados</span></div>${['ok','medio','grave'].map(l=>`<div class="st-${l}"><small>${levelDot(l)}${LEVELS[l][0]}</small><strong>${k(l)}</strong><span>${pct(k(l))}% dos auditados</span></div>`).join('')}</div>
 <div class="shift-split">${[['DIURNO','Diurno','sun'],['NOTURNO','Noturno','moon']].map(([k,l,ic])=>{const cc=cs.filter(c=>(c.data.turno||'')===k),aa=cc.filter(c=>c.data.audit),q=lv=>aa.filter(c=>contractLevel(c)===lv).length,items=AUDIT_CHECKS.map(([kk,lb])=>({lb,n:aa.filter(c=>['medio','grave'].includes(c.data.checks?.[kk]?.level)).length})).filter(x=>x.n);return `<div class="shift-box"><div class="sb-head">${icon(ic)}<strong>${l}</strong></div><div class="sb-nums"><div><small>Contratos</small><b>${cc.length}</b></div><div><small>Cotas lançadas</small><b>${cc.reduce((a,c)=>a+Number(c.data.cotas||0),0)}</b></div><div><small>Auditados</small><b>${aa.length}/${cc.length}</b></div></div><p class="sb-lv"><span>${levelDot('grave')}${q('grave')} vermelhos</span><span>${levelDot('medio')}${q('medio')} amarelos</span><span>${levelDot('ok')}${q('ok')} verdes</span></p>${items.length?`<p class="sb-items">Erros em: ${items.map(x=>`${x.lb} (${x.n})`).join(' · ')}</p>`:''}</div>`}).join('')}</div>${cs.some(c=>!c.data.turno)?`<p class="micro">${plural(cs.filter(c=>!c.data.turno).length,'contrato sem turno','contratos sem turno')} no mês (lançados quando o campo não existia).</p>`:''}
 <div class="cdash-grid"><figure class="chart-card"><figcaption><strong>Contratos auditados por mês</strong><span class="legend">${['ok','medio','grave'].map(l=>`<span>${levelDot(l)}${LEVELS[l][0]}</span>`).join('')}</span></figcaption><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Contratos auditados por mês, por cor">${[0.5,1].map(f=>`<line x1="0" x2="${W}" y1="${base-(base-top)*f}" y2="${base-(base-top)*f}" class="ch-grid"/>`).join('')}<line x1="0" x2="${W}" y1="${base}" y2="${base}" class="ch-base"/>${bars}</svg>
 <table class="sr-only"><thead><tr><th>Mês</th><th>Verdes</th><th>Amarelos</th><th>Vermelhos</th></tr></thead><tbody>${series.map(x=>`<tr><td>${monthLabel(x.mm)}</td><td>${x.ok}</td><td>${x.medio}</td><td>${x.grave}</td></tr>`).join('')}</tbody></table></figure>
 <figure class="chart-card"><figcaption><strong>Onde estão os erros em ${monthLabel(m).split(' ')[0].toLowerCase()}</strong><span class="legend">${['medio','grave'].map(l=>`<span>${levelDot(l)}${LEVELS[l][0]}</span>`).join('')}</span></figcaption><div class="hbars">${items.map(x=>`<div class="hbar"><span class="hbar-l">${x.lb}</span><span class="hbar-t">${x.medio?`<i style="width:${x.medio/imax*100}%;background:${LV_COLORS.medio}" title="${x.lb}: ${x.medio} amarelo(s)"></i>`:''}${x.grave?`<i style="width:${x.grave/imax*100}%;background:${LV_COLORS.grave}" title="${x.lb}: ${x.grave} vermelho(s)"></i>`:''}</span><span class="hbar-v">${x.medio+x.grave?`${x.medio?`<b class="t-medio">${x.medio}</b>`:''}${x.medio&&x.grave?' · ':''}${x.grave?`<b class="t-grave">${x.grave}</b>`:''}`:'<span class="muted">0</span>'}</span></div>`).join('')}</div></figure></div>
 ${people.length?`<div class="section-title"><h2>Por responsável pelo lançamento</h2></div><div class="table-wrap"><table class="count-table people-table"><thead><tr><th>Responsável</th><th>Contratos</th><th>Verdes</th><th>Amarelos</th><th>Vermelhos</th></tr></thead><tbody>${people.map(x=>`<tr><td>${esc(x.n)}</td><td>${x.total}</td><td>${x.ok}</td><td>${x.medio?`<b class="t-medio">${x.medio}</b>`:'0'}</td><td>${x.grave?`<b class="t-grave">${x.grave}</b>`:'0'}</td></tr>`).join('')}</tbody></table></div>`:''}
 ${recent.length?`<div class="section-title"><h2>Erros do mês</h2><small>${recent.length}</small></div><div class="adm-list">${recent.map(c=>{const l=contractLevel(c),its=AUDIT_CHECKS.filter(([kk])=>['medio','grave'].includes(c.data.checks?.[kk]?.level));return `<button class="contract-card lvl-${l}" data-action="adm-contract-open" data-id="${c.id}"><span class="grow"><strong>${esc(c.data.cliente)}</strong><small>${its.map(([kk,lb])=>`${lb}: ${esc(c.data.checks[kk].note||'')}`).join(' · ')}</small><small>Lançado por ${esc(c.data.lancamento?.name||'—')} · auditado em ${dateBR(c.data.audit.date)}</small></span>${icon('chevron','chevron')}</button>`}).join('')}</div>`:''}
 <div class="section-title"><h2>Todos os contratos do mês</h2></div></section>`}
// Cadastro: confere as senhas enquanto a pessoa digita.
document.addEventListener('input',e=>{const f=e.target.closest?.('#signup-form');if(!f||!['password','password2'].includes(e.target.name))return;const a=f.querySelector('[name=password]').value,b=f.querySelector('[name=password2]').value,el=document.getElementById('su-match');if(!el)return;
 el.className='su-match'+(b?a===b&&a.length>=6?' ok':' bad':'');el.textContent=!b?'':a.length<6?'A senha precisa ter pelo menos 6 caracteres.':a===b?'As senhas conferem.':'As senhas ainda não conferem.'});
// Garçom: esconde o conteúdo quando o app perde o foco (lista de apps abertos, troca de janela).
{const guard=on=>{if(typeof isWaiter==='function'&&isWaiter())document.body?.classList.toggle('privacy',on)};
 document.addEventListener('visibilitychange',()=>guard(document.visibilityState==='hidden'));
 window.addEventListener?.('blur',()=>guard(true));window.addEventListener?.('focus',()=>guard(false));window.addEventListener?.('pagehide',()=>guard(true));window.addEventListener?.('pageshow',()=>guard(false))}
